# This implementation assumes the NestedInteger class is provided.
# You should implement the logic using no shortcuts or external libraries.

class NestedInteger:
    def __init__(self, value=None):
        if value is None:
            self._list = []
            self._integer = None
        else:
            self._list = None
            self._integer = value

    def isInteger(self):
        return self._integer is not None

    def add(self, elem):
        if self._list is not None:
            self._list.append(elem)
        else:
            self._list = [elem]
            self._integer = None

    def setInteger(self, value):
        self._integer = value
        self._list = None

    def getInteger(self):
        return self._integer

    def getList(self):
        return self._list

def deserialize(s):
    # Case: single integer
    if s[0] != '[':
        return NestedInteger(int(s))

    stack = []
    num = None # current number
    sign = 1   # current sign
    for i, char in enumerate(s):
        if char == '-':
            sign = -1
        elif char.isdigit():
            if num is None:
                num = 0
            num = num * 10 + int(char)
        elif char == '[':
            stack.append(NestedInteger())
        elif char == ',' or char == ']':
            if num is not None:
                stack[-1].add(NestedInteger(sign * num))
                num = None
                sign = 1
            if char == ']' and len(stack) > 1:
                ni = stack.pop()
                stack[-1].add(ni)
    return stack[0]
